mapper.select:
SELECT *
FROM TravelPlan
WHERE member_id = #{memberId}
ORDER BY updated_at DESC
LIMIT #{offset}, #{pageSize};

SELECT *
FROM TravelPlan
WHERE member_id = #{memberId}
	AND plan_id = #{planId};

SELECT *
FROM PlanDetail
WHERE plan_id = #{planId}
ORDER BY day_no ASC, begin_time ASC;

SELECT COUNT(*)
FROM Place
WHERE place_id = #{placeId}

SELECT COUNT(*)
FROM Scene
WHERE scene_id = #{sceneId}

mapper.update:
UPDATE TravelPlan
SET title = #{title},
	begin_date = #{beginDate},
	end_date = #{endDate},
	memo = #{memo}
WHERE plan_id = #{planId}
	AND member_id = #{memberId}

UPDATE PlanDetail
SET place_id = #{placeId},
	scene_id = #{sceneId},
	day_no = #{dayNo},
	begin_time = #{beginTime}
WHERE plan_id = #{planId}
	AND detail_id = #{detailId}

mapper.delete:
DELETE FROM TravelPlan
WHERE plan_id = #{planId}
	AND member_id = #{memberId}

DELETE FROM PlanDetail
WHERE plan_id = #{planId}
	AND detail_id NOT IN

		#{detailId}
